/**
 * Ownership handover offers, and the one write that moves a workspace from one owner to the next.
 *
 * Every state change is a single synchronous transaction guarded by
 * `status = 'pending'`, so two racing callers can never both resolve the same
 * offer and the workspace is never observable between "old owner demoted" and
 * "new owner promoted".
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, desc, eq, gt, isNull, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  members,
  organizations,
  ownershipHandovers,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMember, toOrganization, toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Member, Role } from "@/types/member";
import type { Organization, OwnershipHandover } from "@/types/organization";

/** One membership row the acceptance rewrote, with the role it held before. */
export interface HandoverRoleChange {
  readonly member: Member;
  readonly from: Role;
  readonly to: Role;
}

export interface AcceptedHandover {
  readonly handover: OwnershipHandover;
  readonly organization: Organization;
  /** In the order they were applied: the promotion, then the demotion. */
  readonly roleChanges: readonly HandoverRoleChange[];
}

/**
 * The org's offer that is still marked pending, whether or not it has lapsed —
 * the caller decides what a lapsed one means for the operation at hand.
 */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Opens an offer, or returns `null` when one is already open. A lapsed offer
 * is retired to `"expired"` first, so it never blocks its successor.
 */
export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: Date,
  expiresAt: Date,
): Promise<OwnershipHandover | null> {
  const stamp = toIsoTimestamp(createdAt);

  return getDb().transaction((tx) => {
    tx.update(ownershipHandovers)
      .set({ status: "expired" })
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.status, "pending"),
          lte(ownershipHandovers.expiresAt, stamp),
        ),
      )
      .run();

    const open = tx
      .select({ id: ownershipHandovers.id })
      .from(ownershipHandovers)
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .get();
    if (open) return null;

    const row = tx
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId,
        fromUserId,
        toUserId,
        status: "pending",
        expiresAt: toIsoTimestamp(expiresAt),
        createdAt: stamp,
        resolvedAt: null,
      })
      .returning()
      .get();

    return toOwnershipHandover(row);
  });
}

/**
 * Closes an open offer without transferring anything. Returns `null` when the
 * offer is no longer open at `at` (already resolved, or lapsed).
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: "declined" | "canceled",
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Accepts an open offer and moves the workspace in one transaction: the new
 * owner is promoted and recorded on the org *before* the previous owner steps
 * down, so no reader — and no statement inside the transaction — ever sees a
 * workspace without an owner. Returns `null` when the offer is no longer open
 * at `at`, or when the offered user is not an active member any more.
 */
export async function acceptHandover(
  orgId: OrgId,
  handoverId: string,
  at: IsoTimestamp,
): Promise<AcceptedHandover | null> {
  return getDb().transaction((tx) => {
    const pending = tx
      .select()
      .from(ownershipHandovers)
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.id, handoverId),
          eq(ownershipHandovers.status, "pending"),
          gt(ownershipHandovers.expiresAt, at),
        ),
      )
      .get();
    if (!pending) return null;

    const liveMember = (userId: string) =>
      tx
        .select()
        .from(members)
        .where(
          and(
            orgPredicate(members.orgId, orgId),
            eq(members.userId, userId),
            isNull(members.archivedAt),
          ),
        )
        .get();

    const incoming = liveMember(pending.toUserId);
    if (!incoming || incoming.status !== "active") return null;
    const outgoing = liveMember(pending.fromUserId);

    const setRole = (memberId: string, role: Role) =>
      tx
        .update(members)
        .set({ role, updatedAt: at })
        .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
        .returning()
        .get();

    const roleChanges: HandoverRoleChange[] = [];

    if (incoming.role !== "owner") {
      const promoted = setRole(incoming.id, "owner");
      roleChanges.push({
        member: toMember(promoted),
        from: incoming.role,
        to: promoted.role,
      });
    }

    const organization = tx
      .update(organizations)
      .set({ ownerId: pending.toUserId, updatedAt: at })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (outgoing && outgoing.role === "owner") {
      const demoted = setRole(outgoing.id, "admin");
      roleChanges.push({
        member: toMember(demoted),
        from: outgoing.role,
        to: demoted.role,
      });
    }

    const accepted = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: at })
      .where(eq(ownershipHandovers.id, pending.id))
      .returning()
      .get();

    return {
      handover: toOwnershipHandover(accepted),
      organization: toOrganization(organization),
      roleChanges,
    };
  });
}

/**
 * Withdraws the org's open offer when `userId` is on either side of it — used
 * when that member leaves the workspace. An offer that had already lapsed is
 * retired as `"expired"` instead. Returns the offers it closed.
 */
export async function closeHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly OwnershipHandover[]> {
  return getDb().transaction((tx) => {
    const involved = and(
      orgPredicate(ownershipHandovers.orgId, orgId),
      eq(ownershipHandovers.status, "pending"),
      or(
        eq(ownershipHandovers.fromUserId, userId),
        eq(ownershipHandovers.toUserId, userId),
      ),
    );

    const lapsed = tx
      .update(ownershipHandovers)
      .set({ status: "expired" })
      .where(and(involved, lte(ownershipHandovers.expiresAt, at)))
      .returning()
      .all();

    const canceled = tx
      .update(ownershipHandovers)
      .set({ status: "canceled", resolvedAt: at })
      .where(involved)
      .returning()
      .all();

    return [...lapsed, ...canceled].map(toOwnershipHandover);
  });
}

