      .where(and(involved, lte(ownershipHandovers.expiresAt, at)))
      .returning()
      .all();

    const canceled = tx
      .update(ownershipHandovers)
      .set({ status: "canceled", resolvedAt: at })
      .where(involved)
      .returning()
      .all();

    return [...lapsed, ...canceled].map(toOwnershipHandover);
  });
}

