sub('''import type { Organization, OrganizationSummary } from "@/types/organization";
''', '''import type {
  Organization,
  OrganizationSummary,
  OwnershipHandover,
} from "@/types/organization";

/** How long an ownership offer stays open: exactly seven days. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;
