s += '''
/**
 * The recorded owner offers the workspace to another active member. Nothing
 * changes hands yet — the offered member has to accept — and only one offer
 * may be open per workspace at a time.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const handover = await handoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    now,
    new Date(now.getTime() + HANDOVER_TTL_MS),
  );
  if (handover === null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  // Addressed to the offered member only; nobody else hears about an offer.
  await notify(orgId, "ownership_handover", [toUserId], {
    title: `You have been offered ownership of ${org.name}`,
    body: "Accept to become the owner of this workspace, or decline the offer.",
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over, whatever role they hold. The
 * swap itself is one transaction in the repository; the role changes it made
 * are then announced exactly like manual ones, followed by the transfer event
 * — all on behalf of the accepting member.
 *
 * The role writes deliberately bypass `updateMemberRole`: the accepting member
 * need not hold `member:update_role`, and because the new owner is promoted
 * before the previous one steps down the last-owner invariant holds throughout.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await requireOfferFor(actor, orgId, now);

  const accepted = await handoverRepo.acceptHandover(
    orgId,
    offer.id,
    toIsoTimestamp(now),
  );
  if (accepted === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  for (const change of accepted.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.member.id,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: accepted.handover.fromUserId,
    toUserId: accepted.handover.toUserId,
  });

  return accepted.organization;
}

/** The offered member turns the offer down; the owner may then offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await requireOfferFor(actor, orgId, now);

  const declined = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(now),
  );
  if (declined === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return declined;
}

/** The recorded owner withdraws the offer they made while it is still open. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const now = new Date();
  const offer = await handoverRepo.findPendingHandover(orgId);
  if (offer === null || hasLapsed(offer, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const canceled = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "canceled",
    toIsoTimestamp(now),
  );
  if (canceled === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return canceled;
}

/** The open offer any member of the workspace may see, or `null`. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const offer = await handoverRepo.findPendingHandover(orgId);
