  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import {
  acceptOwnershipHandover,
  cancelOwnershipHandover,
  declineOwnershipHandover,
  getPendingOwnershipHandover,
  initiateOwnershipHandover,
} from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** The actor as the session layer would mint it now, from stored state. */
async function freshActor(tenant: Tenant, role: Role): Promise<Actor> {
  const actor = await memberService.resolveActor(tenant.userIds[role], tenant.org.id);
  if (!actor) throw new Error(`no live membership for ${role}`);
  return actor;
}

async function roleOf(tenant: Tenant, role: Role): Promise<Role | undefined> {
  return (await memberRepo.findMember(tenant.org.id, tenant.userIds[role]))?.role;
}

function refusal(reason: string) {
  return expect.objectContaining({ name: "OwnershipHandoverError", reason });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("offering a workspace", () => {
  it("opens a pending offer that expires exactly seven days later", async () => {
    const tenant = await createTenant("handover-offer");

    const offer = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(7 * DAY_MS);

    // Any member can see it; nothing has changed hands yet.
    expect(await getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id)).toEqual(offer);
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.owner);
  });

  it("notifies the offered member and nobody else", async () => {
    const tenant = await createTenant("handover-notify");

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const page = await listNotifications(tenant.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        limit: 25,
        cursor: null,
      });
      expect(page.items.map((row) => row.kind), role).toEqual(
        role === "viewer" ? ["ownership_handover"] : [],
      );
    }
  });

  it("is refused to anyone but the recorded owner, even one holding the owner role", async () => {
    const tenant = await createTenant("handover-recorded-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    const secondOwner = await freshActor(tenant, "admin");
    expect(secondOwner.role).toBe("owner");

    await expect(
      initiateOwnershipHandover(secondOwner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    await expect(cancelOwnershipHandover(secondOwner, tenant.org.id)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    expect(await getPendingOwnershipHandover(secondOwner, tenant.org.id)).not.toBeNull();
  });

  it("must go to an active member of the same workspace other than the owner", async () => {
    const tenant = await createTenant("handover-target");
    const other = await createTenant("handover-target-other");
    const removed = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: removed!.id,
    });

    for (const target of [
      "01HZZZNOSUCHUSERXXXXXXXXXX" as UserId,
      other.userIds.member,
      tenant.userIds.viewer,
    ]) {
      await expect(
        initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, target),
      ).rejects.toBeInstanceOf(NotFoundError);
    }

    await expect(
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
    ).rejects.toEqual(refusal("self"));

    expect(await getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
  });

  it("allows one open offer per workspace", async () => {
    const tenant = await createTenant("handover-single");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    await expect(
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).rejects.toEqual(refusal("pending_exists"));

    const racing = await Promise.allSettled([
      cancelOwnershipHandover(tenant.actors.owner, tenant.org.id).then(() =>
        initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
      ),
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ]);
    expect(racing.filter((result) => result.status === "fulfilled")).toHaveLength(1);
  });

  it("is scoped to the actor's workspace on every operation", async () => {
    const tenant = await createTenant("handover-scope");
    const other = await createTenant("handover-scope-other");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const outsider = other.actors.owner;
    await expect(
      initiateOwnershipHandover(outsider, tenant.org.id, tenant.userIds.admin),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(acceptOwnershipHandover(outsider, tenant.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(declineOwnershipHandover(outsider, tenant.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(cancelOwnershipHandover(outsider, tenant.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(getPendingOwnershipHandover(outsider, tenant.org.id)).rejects.toBeInstanceOf(TenantScopeError);

    expect(await getPendingOwnershipHandover(outsider, other.org.id)).toBeNull();
  });
});

describe("accepting an offer", () => {
  it("makes the offered member the owner and steps the previous owner down", async () => {
    const tenant = await createTenant("handover-accept");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);

    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");
    const ownerCounts: number[] = [];
    detachers.push(
      subscribe("member.role_changed", async () => {
        const owners = await memberRepo.listMembers({
          orgId: tenant.org.id,
          role: "owner",
          limit: 25,
          cursor: null,
        });
        ownerCounts.push(owners.total);
      }),
    );

    const org = await acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id);

    expect(org.id).toBe(tenant.org.id);
    expect(org.ownerId).toBe(tenant.userIds.viewer);
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(tenant, "viewer")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
    expect(await getPendingOwnershipHandover(tenant.actors.member, tenant.org.id)).toBeNull();

    const promoted = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const demoted = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(roleChanges).toHaveLength(2);
    expect(roleChanges).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          orgId: tenant.org.id,
          actorId: tenant.userIds.viewer,
          memberId: promoted!.id,
          from: "viewer",
          to: "owner",
        }),
        expect.objectContaining({
          orgId: tenant.org.id,
          actorId: tenant.userIds.viewer,
          memberId: demoted!.id,
          from: "owner",
          to: "admin",
        }),
      ]),
    );
    expect(ownerCounts.every((count) => count >= 1)).toBe(true);

    expect(transfers).toHaveLength(1);
    expect(transfers[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.viewer,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
    });

    await expect(acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
  });

  it("only changes the previous owner's role when the new owner already held it", async () => {
    const tenant = await createTenant("handover-accept-owner");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    const roleChanges = capture("member.role_changed");
    await acceptOwnershipHandover(await freshActor(tenant, "admin"), tenant.org.id);

    expect(roleChanges).toHaveLength(1);
    expect(roleChanges[0]).toMatchObject({ from: "owner", to: "admin" });
    expect(await roleOf(tenant, "admin")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
  });

  it("records the transfer in the audit log", async () => {
    const tenant = await createTenant("handover-audit");
    detachers.push(registerActivityListeners());
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    await acceptOwnershipHandover(tenant.actors.member, tenant.org.id);

    const page = await listActivity(await freshActor(tenant, "member"), {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    const transfer = page.items.filter(
      (row) => row.action === "organization.ownership_transferred",
    );

    expect(transfer).toHaveLength(1);
    expect(transfer[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: {
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.member,
      },
    });
    expect(page.items.filter((row) => row.action === "member.role_changed")).toHaveLength(2);
  });

  it("moves everything that follows the owner to the new one", async () => {
    const tenant = await createTenant("handover-follow");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    await acceptOwnershipHandover(tenant.actors.member, tenant.org.id);

    const newOwner = await freshActor(tenant, "member");
    const previousOwner = await freshActor(tenant, "owner");

    // New-member alerts.
    const joiner = await userRepo.insertUser({
      email: "joiner@handover-follow.test",
      name: "Joiner",
      passwordHash: "seed",
    });
    const joined = await memberRepo.insertMember(tenant.org.id, joiner.id, "member", null);
    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: joiner.id,
      occurredAt: joined.createdAt,
      memberId: joined.id,
      userId: joiner.id,
      role: "member",
    });
    const alertsFor = async (recipientId: UserId) =>
      (
        await listNotifications(newOwner, {
          orgId: tenant.org.id,
          recipientId,
          unreadOnly: false,
          kind: ["member_joined"],
          limit: 25,
          cursor: null,
        })
      ).total;
    expect(await alertsFor(tenant.userIds.member)).toBe(1);
    expect(await alertsFor(tenant.userIds.owner)).toBe(0);

    // Billing.
    const plan = { orgId: tenant.org.id, plan: "enterprise", interval: "monthly" } as const;
    await expect(billingService.changePlan(previousOwner, plan)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    expect((await billingService.changePlan(newOwner, plan)).plan).toBe("enterprise");

    // The previous owner is an ordinary admin now, and only the new owner may offer.
    await expect(
      initiateOwnershipHandover(previousOwner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const previousMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const removed = await memberService.removeMember(newOwner, {
      orgId: tenant.org.id,
      memberId: previousMember!.id,
    });
    expect(removed.archivedAt).not.toBeNull();
  });
});

describe("declining and withdrawing", () => {
  it("lets only the offered member decline, after which the owner may offer again", async () => {
    const tenant = await createTenant("handover-decline");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    await expect(declineOwnershipHandover(tenant.actors.admin, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
    await expect(acceptOwnershipHandover(tenant.actors.owner, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );

    const declined = await declineOwnershipHandover(tenant.actors.member, tenant.org.id);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).toEqual(expect.any(String));

    expect(await getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.owner);
    expect(await roleOf(tenant, "member")).toBe("member");

    await expect(
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("lets the owner withdraw an open offer", async () => {
    const tenant = await createTenant("handover-cancel");

    await expect(cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    const canceled = await cancelOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(canceled.status).toBe("canceled");
    expect(canceled.resolvedAt).toEqual(expect.any(String));

    await expect(declineOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
    await expect(acceptOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toBeInstanceOf(
      OwnershipHandoverError,
    );
  });

  it("withdraws the offer when the offered member is removed", async () => {
    const tenant = await createTenant("handover-target-leaves");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberService.removeMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target!.id,
    });

    expect(await getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id)).toBeNull();
    await expect(acceptOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
    await expect(
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("withdraws the offer when the offering owner is removed", async () => {
    const tenant = await createTenant("handover-owner-leaves");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin!.id,
      role: "owner",
    });
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const owner = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    await memberService.removeMember(await freshActor(tenant, "admin"), {
      orgId: tenant.org.id,
      memberId: owner!.id,
    });

    expect(await getPendingOwnershipHandover(tenant.actors.member, tenant.org.id)).toBeNull();
    await expect(acceptOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
    expect(await roleOf(tenant, "member")).toBe("member");
  });
});

describe("a lapsed offer", () => {
  it("can be acted on until, and not from, seven days after it was made", async () => {
    const madeAt = new Date("2026-05-04T10:00:00.000Z");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(madeAt);

    const tenant = await createTenant("handover-lapse");
    const offer = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(offer.createdAt).toBe(madeAt.toISOString());
    expect(offer.expiresAt).toBe(new Date(madeAt.getTime() + 7 * DAY_MS).toISOString());

    vi.setSystemTime(madeAt.getTime() + 7 * DAY_MS - 1);
    expect(await getPendingOwnershipHandover(tenant.actors.admin, tenant.org.id)).not.toBeNull();

    vi.setSystemTime(madeAt.getTime() + 7 * DAY_MS);
    expect(await getPendingOwnershipHandover(tenant.actors.admin, tenant.org.id)).toBeNull();
    await expect(acceptOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toEqual(
      refusal("expired"),
    );
    await expect(declineOwnershipHandover(tenant.actors.member, tenant.org.id)).rejects.toEqual(
      refusal("expired"),
    );
    await expect(acceptOwnershipHandover(tenant.actors.admin, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );
    await expect(cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)).rejects.toEqual(
      refusal("nothing_pending"),
    );

    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.owner);
    expect(await roleOf(tenant, "member")).toBe("member");
    expect(await roleOf(tenant, "owner")).toBe("owner");

    // It does not block a new offer, which can be accepted just before it lapses in turn.
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    vi.setSystemTime(madeAt.getTime() + 14 * DAY_MS - 1);
    const org = await acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);
    expect(org.ownerId).toBe(tenant.userIds.admin);
  });
});

